import { StorageManagementClient, BlobServiceProperties } from "@azure/arm-storage";
import { DefaultAzureCredential } from "@azure/identity";

// Initialize client
const subscriptionId = "<your-subscription-id>";
const resourceGroupName = "<your-resource-group>";
const accountName = "<your-storage-account>";
const client = new StorageManagementClient(new DefaultAzureCredential(), subscriptionId);

// Set blob versioning enabled
