  isVersioningEnabled: true
};

async function enableBlobVersioning() {
  await client.blobServices.setServiceProperties(resourceGroupName, accountName, properties);
  console.log("Blob versioning enabled.");
}

enableBlobVersioning();
```

This code assumes you have already created the storage account. Note that `isVersioningEnabled` is not part of the storage account creation parameters but is a property of Blob service properties, so you need to call `setServiceProperties` on the `blobServices` client.

Documentation confirms that `isVersioningEnabled` is indeed set through `BlobServiceProperties` and not during initial account creation【3:8†source】. 

For more details, see the [official API docs](https://learn.microsoft.com/javascript/api/@azure/arm-storage/storageaccountcreateparameters?view=azure-node-latest) and the [blob versioning enablement guides](https://learn.microsoft.com/azure/storage/blobs/versioning-enable).","annotations":[{"text":"","start_index":1509,"end_index":1521,"url_citation":{"title":"Azure Storage: Enable blob versioning on storage account ...","url":"https://stackoverflow.com/questions/65605484/azure-storage-enable-blob-versioning-on-storage-account-programmatically"}}]},"bing_searches":[{"text":"@azure/arm-storage StorageManagementClient blobServices setServiceProperties isVersioningEnabled TypeScript","url":"https://www.bing.com/search?q=%40azure%2Farm-storage+StorageManagementClient+blobServices+setServiceProperties+isVersioningEnabled+TypeScript"}],"annotations":null}

